"""Extract versioned parameter and attribute declarations from official ONNX."""

from pathlib import Path
import onnx

assert onnx.__version__ == "1.23.2"
root = Path(__file__).resolve().parents[1]
schemas = onnx.defs.get_all_schemas_with_history()
names = sorted({schema.name for schema in schemas if not schema.domain})
lines = [
    "// Generated by tool/generate_schemas.py from ONNX 1.23.2.",
    "part of '../flutter_onnx.dart';",
    "",
    "const _schemas = <String, Map<int, _Schema>>{",
]


def slots(params):
    options = {"Single": "1", "Optional": "?", "Variadic": "*"}
    return "".join(options[p.option.name] for p in params)


for name in names:
    versions = {}
    last = None
    for version in range(13, 29):
        try:
            schema = onnx.defs.get_schema(name, version)
        except onnx.defs.SchemaError:
            continue
        attrs = {k: v.type.value for k, v in sorted(schema.attributes.items())}
        required = [k for k, v in sorted(schema.attributes.items()) if v.required]
        literal = (
            f"_Schema({schema.min_input}, {schema.max_input}, '{slots(schema.inputs)}', "
            f"{schema.min_output}, {schema.max_output}, '{slots(schema.outputs)}', {attrs}, {required})"
        )
        if literal != last:
            versions[version] = literal
            last = literal
    if versions:
        lines.append(f"  '{name}': {{")
        lines.extend(f"    {ver}: {lit}," for ver, lit in versions.items())
        lines.append("  },")
lines.append("};")
(root / "lib/src/schemas.dart").write_text("\n".join(lines) + "\n")
